create table if not exists public.consent_records (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, categories jsonb not null default '{"strictly_necessary":true,"functional":false,"analytics":false,"marketing":false}'::jsonb, version text not null default '2026-10-15', created_at timestamptz not null default now());
create table if not exists public.plan_limits (plan text primary key, api_calls_per_day integer not null, storage_bytes bigint not null, seats integer not null, integrations integer not null, rate_burst integer not null);
create table if not exists public.usage_counters (user_id uuid not null references auth.users(id) on delete cascade, metric text not null, period_start date not null, used bigint not null default 0, updated_at timestamptz not null default now(), primary key(user_id, metric, period_start));
create table if not exists public.support_tickets (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject text not null check (char_length(subject) between 1 and 160), body_redacted text not null check (char_length(body_redacted) between 1 and 4000), status text not null default 'open' check (status in ('open','pending','resolved','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.auth_audit_log (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete set null, action text not null, ip_hash text, user_agent text, created_at timestamptz not null default now());
insert into public.plan_limits(plan,api_calls_per_day,storage_bytes,seats,integrations,rate_burst) values ('free',100,10485760,1,5,10) on conflict(plan) do nothing;

alter table public.consent_records enable row level security; alter table public.plan_limits enable row level security; alter table public.usage_counters enable row level security; alter table public.support_tickets enable row level security; alter table public.auth_audit_log enable row level security;
drop policy if exists "consent_self" on public.consent_records; create policy "consent_self" on public.consent_records for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists "plan_limits_read" on public.plan_limits; create policy "plan_limits_read" on public.plan_limits for select to authenticated using (true);
drop policy if exists "usage_self" on public.usage_counters; create policy "usage_self" on public.usage_counters for select using (auth.uid() = user_id);
drop policy if exists "tickets_self" on public.support_tickets; create policy "tickets_self" on public.support_tickets for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists "auth_audit_self" on public.auth_audit_log; create policy "auth_audit_self" on public.auth_audit_log for select using (auth.uid() = user_id);
revoke all on table public.consent_records, public.plan_limits, public.usage_counters, public.support_tickets, public.auth_audit_log from anon;
grant select, insert on public.consent_records to authenticated; grant select on public.plan_limits to authenticated; grant select on public.usage_counters to authenticated; grant select, insert, update on public.support_tickets to authenticated; grant select on public.auth_audit_log to authenticated;
